insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('bio-grammar','Przez trzy lata Marta ___ w banku, a potem zmieniła zawód.','["pracowała","przepracowała","będzie pracować"]',0,'Несовершенный вид pracowała описывает длительный фон прошлого.',0),
('bio-grammar','W 2020 roku Marta ___ kurs i dostała certyfikat.','["kończyła","ukończyła","kończy"]',1,'Ukończyła подчёркивает завершённый результат.',1),
('bio-grammar','Kiedy ___ studia, przeprowadził się do Gdańska.','["kończył","ukończył","ukończy"]',1,'Одно завершённое событие предшествует другому: ukończył.',2),
('bio-grammar','Составьте: Сначала она работала в школе, а потом открыла фирму.','["Najpierw pracowała w szkole, a potem założyła firmę.","Najpierw założyła szkołę, bo pracowała firmę.","Pracuje najpierw, potem firma otwierała."]',0,'Najpierw и potem выстраивают хронологию; założyła передаёт достигнутый результат.',3),
('bio-grammar','Co roku Jan ___ za granicę, ale w zeszłym roku ___ w Polsce.','["jeździł; został","pojechał; zostawał","jeździ; zostanie"]',0,'Jeździł описывает повторение, został — единичный завершённый выбор.',4),
('bio-grammar','Составьте: Этот опыт сильно повлиял на мою жизнь.','["To doświadczenie bardzo wpłynęło na moje życie.","To doświadczenie wpływało moje życie bardzo.","Moje życie wpłynęło do doświadczenia."]',0,'Wpłynąć требует na + винительный падеж: na moje życie.',5),
('bio-quiz','Что означает dorastać?','["взрослеть","переезжать","увольняться"]',0,'Dorastać — постепенно становиться взрослым.',0),
('bio-quiz','Po studiach Anna ___ karierę w mediach.','["rozpoczęła","dorastała","wspominała się"]',0,'Rozpocząć karierę — начать профессиональный путь.',1),
('bio-quiz','Как сказать «поворотный момент»?','["punkt zwrotny","ważny kierunek","czas doświadczenia"]',0,'Punkt zwrotny меняет дальнейшее развитие событий.',2),
('bio-quiz','Pracował nad projektem rok i wreszcie ___ cel.','["osiągnął","osiągał się","dorósł na"]',0,'Osiągnął обозначает полученный результат.',3),
('bio-quiz','Która forma opisuje powtarzające się podróże?','["jeździłem","pojechałem","pojadę raz"]',0,'Jeździłem передаёт повторявшееся действие.',4),
('bio-quiz','Ta książka ___ na wybór jej zawodu.','["wpłynęła","przeprowadziła","ukończyła"]',0,'Wpłynąć na — оказать влияние на что-либо.',5),
('bio-quiz','___ było trudno, lecz z czasem wszystko się zmieniło.','["Początkowo","Na końcu wczoraj","Osiągnięcie"]',0,'Początkowo вводит начальный этап истории.',6),
('bio-quiz','Nowa praca ___ ciekawsza, niż oczekiwał.','["okazała się","podjęła się na","zdobyła się"]',0,'Okazać się сообщает, каким что-либо оказалось.',7),
('bio-quiz','Что лучше связывает биографический рассказ?','["najpierw, następnie, z czasem, w końcu","bo, albo, czy, lecz że","wczoraj, jutro, teraz, nigdy"]',0,'Хронологические маркеры делают рассказ связным.',8),
('bio-quiz','Как сказать о завершённом образовании?','["Ukończyłem studia w 2019 roku.","Kończyłem studia i nie wiadomo kiedy.","Studia ukończyć w roku."]',0,'Ukończyłem ясно обозначает завершённый этап.',9),
('bio-reading-check','Gdzie dorastała Joanna?','["W Białymstoku","W Krakowie","Za granicą"]',0,'Йоанна выросла в Белостоке.',0),
('bio-reading-check','Co studiowała?','["Architekturę","Medycynę","Dziennikarstwo"]',0,'Она изучала архитектуру в Варшаве.',1),
('bio-reading-check','Dlaczego pierwsza praca była ważna?','["Zdobyła praktyczne doświadczenie","Od razu została dyrektorką","Mogła wrócić do szkoły"]',0,'Первая работа дала ей практический опыт.',2),
('bio-reading-check','Co było punktem zwrotnym?','["Projekt biblioteki w małym mieście","Wyjazd na wakacje","Zmiana mieszkania w dzieciństwie"]',0,'Работа над библиотекой изменила её профессиональные цели.',3),
('bio-reading-check','Jak zmieniły się jej plany?','["Postanowiła projektować miejsca publiczne","Zrezygnowała z architektury","Chciała pracować wyłącznie sama"]',0,'Она решила заниматься общественными пространствами.',4),
('bio-reading-check','Jaki wniosek wyciąga Joanna?','["Doświadczenia pomagają lepiej rozumieć własne cele","Każdy plan musi pozostać bez zmian","Pierwsza praca zawsze jest najważniejsza"]',0,'В финале она связывает опыт с пониманием собственных целей.',5);
